mapper.select:
SELECT log.id AS id, log.sku_id AS skuId, log.spu_id AS spuId, spu.name AS spuName, sku.sku_code AS skuCode, log.change_type AS changeType, log.before_stock AS beforeStock, log.after_stock AS afterStock, log.before_lock_stock AS beforeLockStock, log.after_lock_stock AS afterLockStock, log.change_quantity AS changeQuantity, log.source_type AS sourceType, log.source_no AS sourceNo, log.remark AS remark, log.create_time AS createTime FROM product_sku_stock_log log LEFT JOIN product_sku sku ON sku.id = log.sku_id AND sku.deleted = 0 LEFT JOIN product_spu spu ON spu.id = log.spu_id AND spu.deleted = 0
AND log.sku_id = #{reqVO.skuId,jdbcType=BIGINT}
AND log.change_type = #{reqVO.changeType,jdbcType=VARCHAR}
AND log.source_type = #{reqVO.sourceType,jdbcType=VARCHAR}
AND log.source_no = #{reqVO.sourceNo,jdbcType=VARCHAR}
ORDER BY log.create_time DESC, log.id DESC
